import type { IconEntry } from "../../src/types";

/** Matches the repository's Prettier `printWidth`, so the generated file passes `format:check`. */
const PRINT_WIDTH = 100;

/**
 * Entries per array literal. TypeScript compares every element type of an array literal with
 * every other, and gives up (TS2590) past about a million comparisons, so one literal of ~1,800
 * icons fails to type-check. Literals of 400 stay far below that however large libraries grow.
 */
const CHUNK_SIZE = 400;

/**
 * Writes `src/catalog.generated.ts`. Generated TypeScript rather than JSON gives consumers types
 * and lets bundlers split the list into its own lazily loaded chunk.
 */
export function renderCatalog(entries: readonly IconEntry[]): string {
  const chunks: string[] = [];
  for (let start = 0; start < entries.length || start === 0; start += CHUNK_SIZE) {
    const body = entries
      .slice(start, start + CHUNK_SIZE)
      .map(renderEntry)
      .join("");
    chunks.push(`const PART_${chunks.length + 1}: readonly IconEntry[] = [\n${body}];\n`);
  }
  const parts = chunks.map((_, index) => `...PART_${index + 1}`).join(", ");
  return [
    "// generated by scripts/build-catalog.ts — do not edit. Run `pnpm build:catalog` instead.",
    'import type { IconEntry } from "./types";',
    "",
    ...chunks,
    `export const ICONS: readonly IconEntry[] = [${parts}];`,
    "",
  ].join("\n");
}

function renderEntry(entry: IconEntry): string {
  const lines = [
    `id: ${quote(entry.id)},`,
    `library: ${quote(entry.library)},`,
    `slug: ${quote(entry.slug)},`,
    `name: ${quote(entry.name)},`,
    `category: ${quote(entry.category)},`,
    ...renderList("otherCategories", entry.otherCategories),
    ...renderList("aliases", entry.aliases),
    `kind: ${quote(entry.kind)},`,
    `color: ${entry.color === null ? "null" : quote(entry.color)},`,
  ];
  return `  {\n${lines.map((line) => `    ${line}\n`).join("")}  },\n`;
}

/** Prettier keeps a string array on one line when it fits and puts one item per line when not. */
function renderList(key: string, items: readonly string[]): string[] {
  const oneLine = `${key}: [${items.map(quote).join(", ")}],`;
  if (`    ${oneLine}`.length <= PRINT_WIDTH) return [oneLine];
  return [`${key}: [`, ...items.map((item) => `  ${quote(item)},`), "],"];
}

function quote(value: string): string {
  return JSON.stringify(value);
}
